            loans[tokenId].debtShares,
            newDebtExchangeRateX96,  // <------ No longer accurate, after re-entrancy
            Math.Rounding.Up
        );
        _requireLoanIsHealthy(tokenId, debt);

        transformedTokenId = 0;

        return tokenId;
    }
